{
                "type": "object",
                "properties": {
                    "vendor": {"type": "string", "description": "Nombre (parcial) del proveedor a filtrar. Vacío = todos."},
                    "date_from": {"type": "string", "description": "Fecha inicio YYYY-MM-DD. Vacío = sin límite."},
                    "date_to": {"type": "string", "description": "Fecha fin YYYY-MM-DD. Vacío = sin límite."},
                    "group_by": {"type": "string", "enum": ["customer", "day", "customer_day", "total"], "description": "Cómo agrupar los totales (customer = agrupa por proveedor)."}
                }
            }

{
                "type": "object",
                "properties": {
                    "partner": {"type": "string", "description": "Nombre (parcial) del cliente o proveedor a filtrar. Vacío = todos."},
                    "date_from": {"type": "string", "description": "Fecha inicio YYYY-MM-DD. Vacío = sin límite."},
                    "date_to": {"type": "string", "description": "Fecha fin YYYY-MM-DD. Vacío = sin límite."},
                    "group_by": {"type": "string", "enum": ["customer", "day", "customer_day", "total"], "description": "Cómo agrupar los totales."},
                    "move_type": {"type": "string", "enum": ["customer", "vendor", "all"], "description": "customer = facturas emitidas, vendor = facturas recibidas, all = ambas."},
                    "pending": {"type": "boolean", "description": "Si es true, filtra solo facturas no pagadas y totaliza el importe pendiente (amount_residual) en vez del total."}
                }
            }

{
                "type": "object",
                "properties": {
                    "lot": {"type": "string", "description": "Nombre exacto del lote, si se menciona uno."},
                    "product": {"type": "string", "description": "Nombre (parcial) del producto, si no se da el nombre exacto del lote."}
                }
            }

{
                "type": "object",
                "properties": {
                    "product": {"type": "string", "description": "Nombre (parcial) o referencia interna (código) del producto a filtrar. Vacío = todos."},
                    "date_from": {"type": "string", "description": "Fecha inicio YYYY-MM-DD. Vacío = sin límite."},
                    "date_to": {"type": "string", "description": "Fecha fin YYYY-MM-DD. Vacío = sin límite."},
                    "group_by": {"type": "string", "enum": ["product", "day", "product_day", "total"], "description": "Cómo agrupar las cantidades."},
                    "direction": {"type": "string", "enum": ["in", "out", "internal"], "description": "Filtra por tipo de movimiento (entrada/salida/interno). Vacío = todos."},
                    "only_boxes": {"type": "boolean", "description": "Si es true, filtra solo productos marcados como caja/envase retornable (is_box=True). Úsalo cuando el usuario pregunte por 'cajas' o 'envases' sin nombrar un producto concreto."}
                }
            }
